import {ProgressCircle} from "@heroui/react";

export function Basic() {
  return (
    <ProgressCircle aria-label="Loading" value={60}>
      <ProgressCircle.Track>
        <ProgressCircle.TrackCircle />
        <ProgressCircle.FillCircle />
      </ProgressCircle.Track>
    </ProgressCircle>
  );
}

import {ProgressCircle} from "@heroui/react";

export function Indeterminate() {
  return (
    <ProgressCircle isIndeterminate aria-label="Loading">
      <ProgressCircle.Track>
        <ProgressCircle.TrackCircle />
        <ProgressCircle.FillCircle />
      </ProgressCircle.Track>
    </ProgressCircle>
  );
}

import {Label, ProgressCircle} from "@heroui/react";

export function WithLabel() {
  return (
    <div className="flex items-center gap-3">
      <ProgressCircle aria-label="Loading" value={75}>
        <ProgressCircle.Track>
          <ProgressCircle.TrackCircle />
          <ProgressCircle.FillCircle />
        </ProgressCircle.Track>
      </ProgressCircle>
      <Label>75% Complete</Label>
    </div>
  );
}

import {ProgressCircle} from "@heroui/react";

export function CustomStyles() {
  return (
    <ProgressCircle
      aria-label="Sync progress"
      className="size-14 text-neutral-700 dark:text-neutral-300"
      value={68}
    >
      <ProgressCircle.Track>
        <ProgressCircle.TrackCircle className="stroke-neutral-200 dark:stroke-neutral-800" />
        <ProgressCircle.FillCircle
          className="stroke-neutral-700 dark:stroke-neutral-300"
          strokeLinecap="round"
        />
      </ProgressCircle.Track>
    </ProgressCircle>
  );
}
